const jwt = require('jsonwebtoken');

async function test() {
  const projectId = process.env.PARAGON_PROJECT_ID;
  const privateKey = process.env.PARAGON_SIGNING_KEY.replace(/\\n/g, '\n');
  const userId = 'test-user-123';
  const actionName = 'CUSTOM_WORKFLOW_TRIGGER';

  const token = jwt.sign(
    {
      sub: userId,
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + (60 * 60)
    },
    privateKey,
    {
      algorithm: 'RS256'
    }
  );

  const url = `https://actionkit.useparagon.com/projects/${projectId}/users/${userId}/actions/${actionName}`;
  console.log('Trying URL:', url);

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      },
      body: JSON.stringify({
        event: "test_event",
        value: 42
      })
    });

    const text = await response.text();
    console.log('Status:', response.status);
    console.log('Response:', text);
  } catch (err) {
    console.error('Error:', err);
  }
}

test();

